"""Build phase24's evidence browser; reads receipts, never runs game code."""
from pathlib import Path
import hashlib,html,json,wave
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'analysis/phase24'
def read(p):return json.loads(Path(p).read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 runtime=read(OUT/'runtime/evidence.json');native_validation=read(OUT/'runtime/validation.json')
 services=read(OUT/'lifecycle/validation.json');integration=read(OUT/'source-integration.json')
 static=read(OUT/'fields-static/analysis-summary.json');contract=read(OUT/'fields-static/verification.json')
 ranking=read(OUT/'fields-static/unknown-producer-ranking.json');life=read(OUT/'runtime/pointer-lifetimes.json')
 acceptance_path=OUT/'acceptance/requirements.json';acceptance=read(acceptance_path)if acceptance_path.exists()else None
 assert all(d['status']=='passed'for d in(runtime,native_validation,services,integration,contract))
 assert services['original_CPU_parent_cases']==1038 and integration['original_CPU_parent_cases']==42
 assert static['remaining_access_count']==341 and static['new_disjoint_count']==10
 assert runtime['frames_both_runs_controls']==728 and runtime['frames_per_route']==182
 assert runtime['cold_boot']is False and runtime['additional_core_memory_writes']==runtime['ancestor_preparation_bytes']==0
 points=read(OUT/'runtime/original-control/checkpoints.json');other=read(OUT/'runtime/observer/checkpoints.json')
 assert len(points)==len(other)==13 and all(a['frame']==b['frame']and a['fields']==b['fields']for a,b in zip(points,other))
 for a in points:
  for variant in('original-control','observer'):
   for key in('image','state','RAM','SRAM'):assert(OUT/'runtime'/variant/a[key]).is_file()
  assert sha(OUT/'runtime/original-control'/a['image'])==sha(OUT/'runtime/observer'/a['image'])
 audio=[]
 for variant in('original-control','observer'):
  path=OUT/'runtime'/variant/'full-audio.wav'
  with wave.open(str(path),'rb')as f:meta=dict(channels=f.getnchannels(),sample_rate=f.getframerate(),sample_frames=f.getnframes(),duration_seconds=f.getnframes()/f.getframerate())
  audio.append(dict(variant=variant,path='runtime/'+variant+'/full-audio.wav',sha256=sha(path),bytes=path.stat().st_size,**meta))
 wanted={0xD805,0xD808,0xF2AF,0xD80B,0xD812,0xD814,0xF2D7,0xD817,0xD987,0xD993,0xD996,0xD999,0xD99C,0xD9A9,0xEA7C,0xD9AC,0xD9E4,0xD9EA,0xD9ED,0xD9F0,0xD9F2,0xD9F8,0xD9FF,0xDA01}
 events=[]
 for line in(OUT/'runtime/observer/events.jsonl').open():
  x=json.loads(line)
  if x['kind']=='opcode_boundary'and x['opcode_PC']in wanted:events.append(x)
 lifecycles=[]
 for x in life['instances']:
  subset=[e for e in events if e['frame']==x['frame']and x['city_pointer_entry_sequence']-2<=e['sequence']<=x['RTS_before_sequence']]
  assert any(e['opcode_PC']==0xD987 for e in subset)and any(e['opcode_PC']==0xD9F0 for e in subset)
  lifecycles.append(dict(**x,events=subset))
 groups=[]
 for x in ranking['groups']:
  groups.append({k:x[k]for k in('group_id','physical_bank','pointer_zero_page','access_count','priority','priority_category','route_discrimination','selected_for_new_context_contract','newly_proved_disjoint_access_count','remaining_unknown_access_count','accesses')})
 assert len(groups)==55 and sum(g['access_count']for g in groups)==270
 callers=[]
 for p in sorted((OUT/'cpu-lifecycle/actual-callers').glob('entry-*/context.json')):
  x=read(p);callers.append(dict(folder=str(p.parent.relative_to(OUT)),context=x))
 assert len(callers)==4 and all(x['context']['N163_origin']=='explicit_shared_fixture_not_Native_snapshot'for x in callers)
 names=('pointer_lifecycle_services.py','pointer_lifecycle_integration.py');sources=[];source_html=[]
 for i,name in enumerate(names,1):
  path=ROOT/'source/recovered'/name;raw=path.read_text();sources.append(dict(file='source/recovered/'+name,sha256=sha(path),UTF8_bytes=len(raw.encode())))
  source_html.append('<details class="source"><summary>'+html.escape(name)+'</summary><p><a href="../../source/recovered/'+name+'">完整 UTF-8 源文件</a> · SHA256 <code>'+sha(path)+'</code></p><pre id="source-code-'+str(i)+'">'+html.escape(raw)+'</pre></details>')
 counts=dict(RTS=services['counts']['actual_caller_RTS']+integration['counts']['returned'],nonlocal_return=integration['counts']['nonlocal_return'],strict_prefix=services['counts']['strict_missing_dependency_prefix'])
 assert counts==dict(RTS=1077,nonlocal_return=1,strict_prefix=2)
 data=dict(native=runtime,points=points,audio=audio,lifecycles=lifecycles,groups=groups,callers=callers,sources=sources,
  source_counts=dict(parent_cases=1080,service_cases=1038,integration_cases=42,guards=services['source_guard_count']+integration['guard_count'],**counts),
  static_summary=static,contract_counts={k:contract[k]for k in('original_contract_CPU_cases','typed_helper_actual_caller_RTS_CPU_cases','D805_actual_caller_RTS_CPU_cases','raw_alias_counterexample_CPU_cases','model_guard_check_count')},
  acceptance=acceptance,acceptance_path='acceptance/requirements.json',acceptance_sha256=sha(acceptance_path)if acceptance else None)
